# POST /api/sheets/{sheetId}/people/{personId}/hold — add a hold on the person from a from-date
# (blank: the sheet's today) to an optional to-date; a date that is not a date, or a to-date before
# the from-date, is refused. Only their OPEN claims dated within a hold, and not bound by a
# statement, count in no live total.
# A viewer may change nothing: refused before anything is read or written.
guard:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: validate
validate:
  class: net.officefloor.hq.app.person.ValidateHold
  next: before
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: hold
hold:
  class: net.officefloor.hq.app.person.HoldPerson
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.person.RecordPersonHold
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Binds the hold's dates: null when blank; a date that is not a date, or a to-date before the
 *  from-date, is refused. */
public class ValidateHold {
    public void validate(@RequestBody HoldRequest request, Out<HoldRequest> body)
            throws InvalidPersonException {
        String from = date(request == null ? null : request.from());
        String to = date(request == null ? null : request.to());
        if (from != null && to != null && to.compareTo(from) < 0) {
            throw new InvalidPersonException("The hold ends before it starts: " + from + " to " + to);
        }
        body.set(new HoldRequest(from, to));
    }

    private static String date(String text) throws InvalidPersonException {
        String value = text == null ? "" : text.trim();
        if (value.isEmpty()) {
            return null;
        }
        try {
            return LocalDate.parse(value).toString();
        } catch (DateTimeParseException e) {
            throw new InvalidPersonException("Not a date: " + value);
        }
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadPerson {
    public void load(@PathVariable("sheetId") String sheetId,
            @PathVariable("personId") long personId, PersonRepository people,
            Out<Person> person) throws PersonNotFoundException {
        Person found = people.find(sheetId.trim(), personId);
        if (found == null) {
            throw new PersonNotFoundException(personId);
        }
        person.set(found);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Adds a hold on the person from the date asked (the sheet's today when none) to the to-date asked
 *  (none: open-ended); a to-date before a defaulted from-date is refused. */
public class HoldPerson {
    public void hold(@RequestParam(name = "by", required = false) String by, @Val HoldRequest request,
            @Val Person person, SheetRepository sheets, PersonRepository people)
            throws InvalidPersonException {
        String from = request.from() != null ? request.from() : sheets.today(person.getSheetId()).toString();
        if (request.to() != null && request.to().compareTo(from) < 0) {
            throw new InvalidPersonException("The hold ends before it starts: " + from + " to " + request.to());
        }
        people.addHold(person, new Hold(from, request.to()), by == null ? "" : by);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Records the hold just added (PERSON_HELD) with its from-date. */
public class RecordPersonHold {
    public void record(@RequestParam(name = "by", required = false) String by,
            @Val Person person, Audit audit) {
        Hold hold = person.getHolds().get(person.getHolds().size() - 1);
        audit.record("PERSON_HELD sheet=" + person.getSheetId() + " by=" + (by == null ? "" : by)
                + " name=" + person.getName() + " from=" + hold.from());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPerson {
    public void respond(@Val Person person, ObjectResponse<Person> response) {
        response.send(person);
    }
}

